try {
    // 1. 轉移 StudentClass
    \$sc = DB::table('StudentClass')->where('TeacherID', \$fromId)->update(['TeacherID' => \$toId]);
    echo 'StudentClass updated: ' . \$sc . ' rows' . PHP_EOL;

    // 2. 轉移 LearningRecord
    \$lr = DB::table('LearningRecord')->where('TeacherID', \$fromId)->update(['TeacherID' => \$toId]);
    echo 'LearningRecord updated: ' . \$lr . ' rows' . PHP_EOL;

    // 3. 轉移 StudentSingIn（以防）
    \$si = DB::table('StudentSingIn')->where('TeacherID', \$fromId)->update(['TeacherID' => \$toId]);
    echo 'StudentSingIn updated: ' . \$si . ' rows' . PHP_EOL;

    // 4. 轉移 schedules
    \$sch = DB::table('schedules')->where('teacher_id', \$fromId)->update(['teacher_id' => \$toId]);
    echo 'schedules updated: ' . \$sch . ' rows' . PHP_EOL;

    DB::commit();
    echo '✓ 資料轉移完成' . PHP_EOL;
} catch (\Exception \$e) {
    DB::rollBack();
    echo '✗ 錯誤：' . \$e->getMessage() . PHP_EOL;
}
"

