    ->select([
        'cs.id', 'cs.StudentClassID', 'cs.SessionDate', 'cs.StartTime', 'cs.EndTime', 'cs.Status',
        'sc.TeacherID', 's.CampusID', 's.name as student_name',
        DB::raw('COALESCE(sub.Subject_Name, \"\") as subject_name'),
    ])
    ->where('cs.id', 3547)
    ->first();
echo json_encode(\$row, JSON_PRETTY_PRINT) . PHP_EOL;
"

